-- Holiday group departures: a booking on a departure records it and how many travellers it
-- takes, so seats left = seats − travellers on active bookings (checked in the booking batch).
ALTER TABLE bookings ADD COLUMN departure_id TEXT;
ALTER TABLE bookings ADD COLUMN travellers INTEGER NOT NULL DEFAULT 0;
CREATE INDEX bookings_by_departure ON bookings (departure_id) WHERE departure_id IS NOT NULL;
